<article class="essay-row"><div class="essay-category small-label"><?php $cats = get_the_category(); echo esc_html( $cats ? $cats[0]->name : 'Notes' ); ?></div><div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( get_the_excerpt() ); ?></p><div class="essay-meta"><?php echo esc_html( get_the_date( 'M j, Y' ) ); ?> <span>·</span> <?php echo esc_html( adi_reading_minutes( get_the_content() ) ); ?> min read</div></div><a class="icon-link" href="<?php the_permalink(); ?>" aria-label="<?php echo esc_attr( 'Read ' . get_the_title() ); ?>"><?php echo adi_arrow(); ?></a></article>
